 static void ClipSidewalk(Transform target,Transform source){var plan=JsonUtility.FromJson<ClipPlan>(File.ReadAllText(Path.Combine(Reports,"screenshot-coast-plan.json")));var src=source.GetComponent<MeshFilter>().sharedMesh;var ov=src.vertices;var on=src.normals;var ou=src.uv;var verts=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector2>();var parts=new List<int[]>();foreach(var part in plan.nativeSidewalkCut){int off=verts.Count;foreach(var w in part.vertices){verts.Add(ov[w.i0]*w.a+ov[w.i1]*w.b+ov[w.i2]*w.c);normals.Add((on[w.i0]*w.a+on[w.i1]*w.b+on[w.i2]*w.c).normalized);uv.Add(ou[w.i0]*w.a+ou[w.i1]*w.b+ou[w.i2]*w.c);}parts.Add(part.triangles.Select(i=>i+off).ToArray());}var m=new Mesh{indexFormat=IndexFormat.UInt32};m.SetVertices(verts);m.SetNormals(normals);m.SetUVs(0,uv);m.subMeshCount=parts.Count;for(int i=0;i<parts.Count;i++)m.SetTriangles(parts[i],i);m.RecalculateBounds();target.GetComponent<MeshFilter>().sharedMesh=SaveMesh(m,"NativeCoastPaving_RoadClearance");FixCollider(target);}
 static void FixRestaurant(Transform building){var back=building.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name=="AR_Restaurant_BackWall");foreach(var r in building.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("AR_Restaurant_KitchenSideWall"))){var f=r.GetComponent<MeshFilter>();var m=Object.Instantiate(f.sharedMesh);var v=m.vertices;for(int i=0;i<v.Length;i++){var p=r.transform.TransformPoint(v[i]);if(p.x>back.bounds.min.x-.002f)p.x=back.bounds.min.x-.002f;v[i]=r.transform.InverseTransformPoint(p);}m.vertices=v;m.RecalculateBounds();f.sharedMesh=SaveMesh(m,"RestaurantCorner_"+applied.restaurantCorners++);FixCollider(r.transform);}}
 static void AddCinemaSeats(Scene gs,Transform room,EmoteArea template){if(room.Find("NativeAuditoriumSeats"))return;var root=new GameObject("NativeAuditoriumSeats").transform;root.SetParent(room,false);foreach(var seat in room.GetComponentsInChildren<MeshRenderer>(true).Where(r=>Regex.IsMatch(r.name,@"Seat_R.*_Cushion$"))){var b=seat.bounds;var back=room.GetComponentsInChildren<MeshRenderer>(true).FirstOrDefault(r=>r.name==seat.name.Replace("_Cushion","_BackShell"));var facing=back?Vector3.ProjectOnPlane(b.center-back.bounds.center,Vector3.up).normalized:room.forward;var pose=new Vector3(b.center.x,b.max.y-.46f,b.center.z);var go=Object.Instantiate(template.gameObject,root);go.name="CinemaSeat_"+applied.cinemaSeats.ToString("000");go.transform.SetPositionAndRotation(pose,Quaternion.LookRotation(facing));go.transform.localScale=Vector3.one;var dining=go.GetComponent<SushiAndFish.CityExpansion.CityDiningSeat>();if(dining)Object.DestroyImmediate(dining);var area=go.GetComponent<EmoteArea>();Set(area,"_emote",0);Set(area,"_targetPos",pose);Set(area,"_targetRot",go.transform.eulerAngles);Set(area,"_allowOpenEmotesInput",false);var anchor=area.WorldUIAnchor;Set(anchor,"_worldOffset",Vector3.up*.7f);Set(anchor,"_maxDistance",3.5f);var sphere=go.GetComponent<SphereCollider>();sphere.radius=.3f;sphere.center=Vector3.up*.5f;sphere.isTrigger=true;var net=go.GetComponent<NetworkObject>();var so=new SerializedObject(net);so.FindProperty("GlobalObjectIdHash").longValue=(uint)Animator.StringToHash("SushiAndFish.CinemaSeat.20261021."+applied.cinemaSeats);so.ApplyModifiedPropertiesWithoutUndo();applied.cinemaSeats++;}if(applied.cinemaSeats==0)throw new Exception("No auditorium seat cushion meshes matched");}
 static float Floor(Vector3 p,Transform exclude){float h=float.NegativeInfinity;foreach(var hit in Physics.RaycastAll(new Vector3(p.x,4.8f,p.z),Vector3.down,9,~0,QueryTriggerInteraction.Ignore)){if(exclude&&(hit.transform==exclude||hit.transform.IsChildOf(exclude)))continue;if(hit.normal.y<.5f||hit.collider.name.Contains("Bench"))continue;h=Mathf.Max(h,hit.point.y);}return h;}
 static void AlignBenches(Transform[] nodes){foreach(var t in nodes.Where(t=>P(t).StartsWith("Root/Bench/")&&t.GetComponent<MeshRenderer>())){var b=t.GetComponent<Renderer>().bounds;float support=Floor(b.center,t);if(float.IsNegativeInfinity(support)||support-b.min.y<.004f||support-b.min.y>1.1f)continue;float delta=support+.008f-b.min.y;var row=new BenchFix{path=P(t),oldY=b.min.y,newY=support+.008f,support=support,delta=delta};t.position+=Vector3.up*delta;foreach(var area in nodes.Select(x=>x.GetComponent<EmoteArea>()).Where(a=>a&&!P(a.transform).Contains("CityBuildings")&&Vector2.Distance(new Vector2(a.transform.position.x,a.transform.position.z),new Vector2(b.center.x,b.center.z))<1.05f)){area.transform.position+=Vector3.up*delta;var so=new SerializedObject(area);var pos=so.FindProperty("_targetPos");pos.vector3Value+=Vector3.up*delta;so.ApplyModifiedPropertiesWithoutUndo();row.playerAreas++;}foreach(var anchor in nodes.Select(x=>x.GetComponent<WaypointAnchor>()).Where(a=>a&&a.Category==ResidentActivityType.SeasideBench&&Vector2.Distance(new Vector2(a.transform.position.x,a.transform.position.z),new Vector2(b.center.x,b.center.z))<1.05f)){anchor.transform.position+=Vector3.up*delta;Set(anchor,"_useAuthoredPose",true);Set(anchor,"_autoSnapInEditor",false);Set(anchor,"_moveTransformToNavMesh",false);row.npcAnchors++;}applied.benches.Add(row);}}
 static void RestoreTerrain(Transform[] sources,Transform[] nodes){var maps=JsonUtility.FromJson<Maps>(File.ReadAllText(Path.Combine(Reports,"island-trim-edit-audit.json")));var bounds=sources.Select(t=>t.GetComponent<Renderer>().bounds).ToArray();var range=bounds[0];foreach(var b in bounds)range.Encapsulate(b);range.Expand(23);var walk=nodes.Select(t=>t.GetComponent<MeshCollider>()).Where(c=>c&&Regex.IsMatch(c.name,@"stairs|street|sidewalk|SideWalk",RegexOptions.IgnoreCase)&&!P(c.transform).Contains("TownRoadNetwork")).ToArray();foreach(var terrain in nodes.Select(t=>t.GetComponent<Terrain>()).Where(t=>t)){var map=maps.terrains.FirstOrDefault(m=>m.path==P(terrain.transform));if(map==null)continue;var data=terrain.terrainData;BackupAsset(AssetDatabase.GetAssetPath(data));var src=AssetDatabase.LoadAssetAtPath<TerrainData>(map.originalData);var origin=terrain.transform.position;var size=data.size;int n=data.heightmapResolution;var old=data.GetHeights(0,0,n,n);var native=src.GetHeights(0,0,n,n);int changes=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=new Vector3(origin.x+x/(float)(n-1)*size.x,0,origin.z+z/(float)(n-1)*size.z);if(p.x<range.min.x||p.x>range.max.x||p.z<range.min.z||p.z>range.max.z)continue;float dist=float.PositiveInfinity;foreach(var b in bounds){float dx=Mathf.Max(b.min.x-p.x,0,p.x-b.max.x),dz=Mathf.Max(b.min.z-p.z,0,p.z-b.max.z);dist=Mathf.Min(dist,Mathf.Sqrt(dx*dx+dz*dz));}if(dist>11)continue;float blend=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(6,11,dist));float target=Mathf.Lerp(old[z,x],native[z,x],blend);float world=origin.y+target*size.y;float highestWalk=float.NegativeInfinity;foreach(var c in walk){if(p.x<c.bounds.min.x||p.x>c.bounds.max.x||p.z<c.bounds.min.z||p.z>c.bounds.max.z)continue;if(c.Raycast(new Ray(new Vector3(p.x,c.bounds.max.y+1,p.z),Vector3.down),out var hit,c.bounds.size.y+2)&&hit.normal.y>.25f)highestWalk=Mathf.Max(highestWalk,hit.point.y);}if(!float.IsNegativeInfinity(highestWalk))world=Mathf.Min(world,highestWalk-.055f);targ