 public static void ApplyAll(){applied=new ApplyReceipt{utc=DateTime.UtcNow.ToString("o")};ApplyStage("BEGIN");try{BackupAsset(GS);BackupAsset(DS);Directory.CreateDirectory(Output);AssetDatabase.Refresh();var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);Physics.SyncTransforms();var current=All(gs).Concat(All(ds)).ToArray();var source=EditorSceneManager.OpenScene(Source,OpenSceneMode.Additive);Physics.SyncTransforms();var allSource=All(source);var native=allSource.Where(t=>t.GetComponent<MeshFilter>()&&t.GetComponent<MeshRenderer>()&&Coastal(t)).ToArray();var tunnel=allSource.Where(t=>P(t).StartsWith("Root/TunnelComp/")&&t.name.StartsWith("SM_fence")&&t.GetComponent<Renderer>()).ToArray();foreach(var t in current.Where(t=>t.GetComponent<MeshRenderer>()&&tunnel.Any(s=>SameBounds(t.GetComponent<Renderer>().bounds,s.GetComponent<Renderer>().bounds)))){Object.DestroyImmediate(t.gameObject);applied.tunnelRailsRemoved++;}var root=ds.GetRootGameObjects().FirstOrDefault(g=>g.name=="SourceCoastCompletion_20261021");if(!root){root=new GameObject("SourceCoastCompletion_20261021");SceneManager.MoveGameObjectToScene(root,ds);}var renderers=current.Where(t=>t&&t.GetComponent<MeshRenderer>()).ToList();foreach(var t in native){var b=t.GetComponent<Renderer>().bounds;var existing=renderers.FirstOrDefault(x=>x&&SameBounds(x.GetComponent<Renderer>().bounds,b));if(existing){FixCollider(existing);continue;}var g=new GameObject(t.name);g.transform.SetParent(root.transform,false);g.transform.SetPositionAndRotation(t.position,t.rotation);g.transform.localScale=t.lossyScale;g.AddComponent<MeshFilter>().sharedMesh=t.GetComponent<MeshFilter>().sharedMesh;g.AddComponent<MeshRenderer>().sharedMaterials=t.GetComponent<MeshRenderer>().sharedMaterials;if(t.name=="SideWalkTerrainEdge")ClipSidewalk(g.transform,t);else FixCollider(g.transform);applied.structures.Add(P(t));applied.restored++;renderers.Add(g.transform);}ApplyStage("SOURCE_ASSEMBLIES_